svg.script:
// Interactive only where scripts run (inline or <object>); as a plain <img> it just loops.
(function () {
  var svg = document.documentElement, LOOP = 65, delay = 0;
  var pausedAt = null, lost = 0;
  var now = function () { return performance.now() / 1000; };
  var clock = function () { return now() - lost - (pausedAt === null ? 0 : now() - pausedAt); };

  function seek(t) {
    delay = clock() - t;
    svg.style.setProperty('--seek', delay + 's');
  }
  function chapter(step) {
    var pos = ((clock() - delay) % LOOP + LOOP) % LOOP, i = 0;
    for (var n = 0; n < STOPS.length; n++) if (pos >= STOPS[n] - 0.25) i = n;
    seek(STOPS[(i + step + STOPS.length) % STOPS.length]);
  }
  function toggle() {
    if (pausedAt === null) { pausedAt = now(); svg.classList.add('paused'); }
    else { lost += now() - pausedAt; pausedAt = null; svg.classList.remove('paused'); }
    document.getElementById('ppPlay').style.opacity = pausedAt === null ? 0 : 1;
    document.getElementById('ppPause').style.opacity = pausedAt === null ? 1 : 0;
  }

  var STOPS = [];
  [].forEach.call(document.querySelectorAll('[data-t]'), function (el) {
    var t = parseFloat(el.getAttribute('data-t'));
    STOPS.push(t);
    el.addEventListener('click', function () { seek(t); });
    el.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); seek(t); } });
  });
  STOPS.sort(function (a, b) { return a - b; });

  var pp = document.getElementById('pp');
  pp.addEventListener('click', toggle);
  pp.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); } });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight') chapter(1);
    else if (e.key === 'ArrowLeft') chapter(-1);
    else return;
    e.preventDefault();
  });

})();
